import java.util.*;

public class Solution {
    private static long[] dist;
    private static int[] pai;

    private static void rodar(int n, int[][] arestas, int origem) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : arestas) adj.get(e[0]).add(new int[]{e[1], e[2]});
        dist = new long[n];
        pai = new int[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        Arrays.fill(pai, -1);
        dist[origem] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(x -> x[0]));
        pq.add(new long[]{0, origem});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            int u = (int) top[1];
            if (top[0] > dist[u]) continue; // entrada obsoleta
            for (int[] e : adj.get(u)) {
                long nd = dist[u] + e[1];
                if (nd < dist[e[0]]) {
                    dist[e[0]] = nd;
                    pai[e[0]] = u;
                    pq.add(new long[]{nd, e[0]});
                }
            }
        }
    }

    static long[] distancias(int n, int[][] arestas, int origem) {
        rodar(n, arestas, origem);
        return dist;
    }

    static List<Integer> caminho(int n, int[][] arestas, int origem, int destino) {
        rodar(n, arestas, origem);
        if (dist[destino] == Long.MAX_VALUE) return List.of();
        LinkedList<Integer> out = new LinkedList<>();
        for (int v = destino; v != -1; v = pai[v]) out.addFirst(v);
        return out;
    }
}

