import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static final int[][] G = {{0, 1, 4}, {0, 2, 1}, {2, 1, 2}, {1, 3, 1}, {2, 3, 5}, {3, 4, 3}};

    @Test void distancias() {
        assertArrayEquals(new long[]{0, 3, 1, 4, 7}, Solution.distancias(5, G, 0));
    }

    @Test void caminho() {
        assertEquals(List.of(0, 2, 1, 3, 4), Solution.caminho(5, G, 0, 4));
        assertEquals(List.of(0), Solution.caminho(5, G, 0, 0));
    }

    @Test void inalcancavel() {
        assertEquals(List.of(), Solution.caminho(3, new int[][]{{0, 1, 1}}, 0, 2));
        assertEquals(Long.MAX_VALUE, Solution.distancias(3, new int[][]{{0, 1, 1}}, 0)[2]);
    }

    @Test void pesosGrandesSemOverflow() {
        int n = 10;
        int[][] e = new int[n - 1][];
        for (int i = 0; i + 1 < n; i++) e[i] = new int[]{i, i + 1, 1_000_000_000};
        assertEquals(9_000_000_000L, Solution.distancias(n, e, 0)[n - 1]);
    }

    @Test void grandeAleatorio() {
        var rnd = new Random(6);
        int n = 50_000;
        int[][] e = new int[200_000][];
        for (int i = 0; i < e.length; i++) e[i] = new int[]{rnd.nextInt(n), rnd.nextInt(n), rnd.nextInt(1000)};
        long[] d = Solution.distancias(n, e, 0);
        for (int[] a : e) if (d[a[0]] != Long.MAX_VALUE) assertTrue(d[a[1]] <= d[a[0]] + a[2]);
    }
}
